from collections import deque


def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == grid[0][0] or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            cells = set()
            while q:
                y, x = q.pop()
                cells.add((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); q.append((yy,xx))
            comps.append((color, cells))
    return comps


def transform(grid):
    out = [row[:] for row in grid]
    comps = _components(grid)
    markers = []
    for color, cells in comps:
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
        height, width = r1-r0+1, c1-c0+1
        if len(cells) != height + width - 1 or height < 3 or width < 3:
            continue
        elbow = None
        for r in (r0, r1):
            for c in (c0, c1):
                if ((r, c) in cells
                    and all((r, x) in cells for x in range(c0,c1+1))
                    and all((y, c) in cells for y in range(r0,r1+1))):
                    elbow = (r, c)
                    break
            if elbow is not None:
                break
        if elbow is not None:
            markers.append((color, cells, elbow, (r0,r1,c0,c1)))

    for color, marker, (er,ec), (r0,r1,c0,c1) in markers:
        # The open side is opposite the vertical arm: down-right for an
        # upward stem, up-left for a downward stem.
        stem_up = er == r1
        horiz_lo, horiz_hi = c0, c1
        all_candidates = []
        aligned = []
        for other_color, cells in comps:
            if cells is marker:
                continue
            rs = [r for r,c in cells]
            cs = [c for r,c in cells]
            cr = (min(rs)+max(rs))/2
            cc = (min(cs)+max(cs))/2
            if stem_up:
                if min(rs) <= er or cc < ec:
                    continue
            else:
                if max(rs) >= er or max(cs) >= ec:
                    continue
            dist = min(abs(r-er)+abs(c-ec) for r,c in cells)
            item = (dist, other_color, cells, (min(rs),max(rs),min(cs),max(cs)))
            all_candidates.append(item)
            if min(cs) <= horiz_hi and max(cs) >= horiz_lo:
                aligned.append(item)

        candidates = aligned
        if not candidates:
            # If no object lies under/beyond the horizontal arm, use the
            # closest object whose major axis follows the longer L arm.
            if r1-r0+1 > c1-c0+1:
                wanted = 'vertical'
            elif c1-c0+1 > r1-r0+1:
                wanted = 'horizontal'
            else:
